  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;
  if (result.status !== 0) {
    return unknown(`\\`wrangler ${argv.join(' ')}\\` failed — ${firstUsefulLine(output) || `exit ${result.status}`}`);
  }"""
assert old in s, 'anchor not found'
s = s.replace(old, new)

helper = """/** Colour codes and wrangler's log-file footer, out of the way of the actual reason. */
function firstUsefulLine(output: string): string {
  return output
    // eslint-disable-next-line no-control-regex -- ANSI escapes are exactly what is being stripped
    .replace(/\\u001b\\[[0-9;]*m/g, '')
    .split('\\n')
    .map((line) => line.replace(/^[\\s✘▲]+/, '').trim())
    .filter(Boolean)
    .filter((line) => !line.startsWith('Logs were written'))
    .filter((line) => !line.includes('rerun this command with'))
    .filter((line) => !/^\\[?(ERROR|WARNING)\\]?$/i.test(line))
    .map((line) => line.replace(/^\\[?(ERROR|WARNING)\\]?\\s*/i, ''))
    .find((line) => line.length > 12) ?? '';
}

"""
s = s.replace('/**\\n * Asks wrangler', helper + '/**\\n * Asks wrangler')
if helper not in s:
    s = s.replace('/**\n * Asks wrangler', helper + '/**\n * Asks wrangler')
assert helper in s, 'helper not inserted'
